const allItems = $input.all();

// 1. Danh sách các cột master cần kế thừa dữ liệu
const MASTER_FIELDS = [
  "Mục đích chính",
  "Thông tin thương hiệu/sản phẩm/dịch vụ/USP",
  "Chân dung & Insight khách hàng",
  "Kênh triển khai",
  "Mục tiêu kinh doanh/marketing",
  "Mục tiêu đầu ra",
  "Định dạng nội dung",
  "Độ dài nội dung",
  "Số phiên bản nội dung",
  "Công thức nội dung (Copywriting formula)",
  "Văn phong",
  "Văn phong & Giọng điệu",
  "Hành động mong muốn (CTA)",
  "Tỷ lệ Văn nói - Văn viết",
  "Tỷ lệ Định tính - Định lượng",
  "Số liệu - bằng chứng uy tín",
  "Prompt bổ sung / luật riêng",
  "Kho Media Drive"
];

// Các từ khóa tiêu đề / hướng dẫn mẫu cần BỎ QUA
const IGNORE_PATTERNS = [
  "bắt buộc", "tùy chọn", "tùy ý", "chưa có",
  "mục đích chính", "mục đích & thương hiệu", "thông tin thương hiệu",
  "kênh triển khai", "khách hàng mục tiêu", "mục tiêu kinh doanh",
  "mục tiêu đầu ra", "định dạng nội dung", "độ dài nội dung",
  "tuyến nội dung", "thông tin ảnh", "tiêu chuẩn ảnh",
  "caption", "bài viết", "text trơn", "ảnh", "video"
];

// Hàm kiểm tra 1 giá trị có phải dữ liệu thật hợp lệ hay không
function isValidDataValue(val) {
  if (val === undefined || val === null) return false;
  const str = String(val).trim();
  if (str === "" || str.startsWith("http") || str.startsWith("[Tùy chọn]")) return false;

  const lower = str.toLowerCase();

  // Bỏ qua số từ (vd: "200 từ", "300 từ", "400 từ", "500 từ")
  if (/^\d+\s*từ$/i.test(str)) return false;
  // Bỏ qua số phiên bản (vd: "1 phiên bản", "3 phiên bản")
  if (/^\d+\s*(phiên bản|bản)$/i.test(str)) return false;
  // Bỏ qua câu hướng dẫn dài trong template Sheet
  if (
    lower.includes("kim chỉ nam") || 
    lower.includes("ngữ cảnh") || 
    lower.includes("gợi ý hook") || 
    lower.includes("đặc thù") || 
    lower.includes("dùng khi") || 
    lower.includes("xác định")
  ) return false;

  // Bỏ qua các từ khóa header
  if (IGNORE_PATTERNS.includes(lower)) return false;

  return true;
}

// Hàm quét lấy đại diện Chủ đề phễu từ các cột phễu
function getFunnelTopic(row) {
  const keys = Object.keys(row);
  for (const k of keys) {
    const kLower = k.toLowerCase().trim();
    if (
      kLower === "col_14" || kLower === "col_13" || kLower === "col_12" || kLower === "col_11" ||
      kLower.includes("chủ đề phễu") || kLower.includes("tuyến nội dung") ||
      kLower.includes("phễu lạnh") || kLower.includes("phễu ấm") || kLower.includes("phễu nóng")
    ) {
      const val = row[k];
      if (isValidDataValue(val)) {
        return String(val).trim();
      }
    }
  }
  return "";
}

// 2. Lọc bỏ các dòng Header / Hướng dẫn mẫu (Dòng 1-4 trong Sheet)
const dataItems = allItems.filter(item => {
  const row = item.json;
  const md = String(row["Mục đích chính"] || "").trim().toLowerCase();
  const kn = String(row["Kênh triển khai"] || "").trim().toLowerCase();

  if (md === "mục đích chính" || md === "mục đích & thương hiệu" || md === "bắt buộc" || md.includes("kim chỉ nam")) return false;
  if (kn === "kênh triển khai" || kn === "bắt buộc" || kn.includes("đặc thù")) return false;

  return true;
});

// 3. Thực hiện kế thừa 2 chiều (Forward Fill + Backward Fill)
const rows = dataItems.map(item => ({ ...item.json }));
let lastValidData = {};

// --- PASS 1: FORWARD FILL (Tải từ trên xuống) ---
for (let i = 0; i < rows.length; i++) {
  const row = rows[i];

  // Kế thừa các cột Master
  MASTER_FIELDS.forEach(field => {
    const val = row[field];
    if (isValidDataValue(val)) {
      lastValidData[field] = String(val).trim();
    } else if (lastValidData[field]) {
      row[field] = lastValidData[field];
    }
  });

  // Kế thừa Tiêu chuẩn ảnh 1, 2, 3
  const tc1 = row["Tiêu chuẩn ảnh 1"];
  const tc2 = row["Tiêu chuẩn ảnh 2"] || row["col_30"];
  const tc3 = row["Tiêu chuẩn ảnh 3"] || row["col_31"];

  if (isValidDataValue(tc1)) lastValidData["Tiêu chuẩn ảnh 1"] = String(tc1).trim();
  else if (lastValidData["Tiêu chuẩn ảnh 1"]) row["Tiêu chuẩn ảnh 1"] = lastValidData["Tiêu chuẩn ảnh 1"];

  if (isValidDataValue(tc2)) lastValidData["Tiêu chuẩn ảnh 2"] = String(tc2).trim();
  else if (lastValidData["Tiêu chuẩn ảnh 2"]) row["Tiêu chuẩn ảnh 2"] = lastValidData["Tiêu chuẩn ảnh 2"];

  if (isValidDataValue(tc3)) lastValidData["Tiêu chuẩn ảnh 3"] = String(tc3).trim();
  else if (lastValidData["Tiêu chuẩn ảnh 3"]) row["Tiêu chuẩn ảnh 3"] = lastValidData["Tiêu chuẩn ảnh 3"];

  delete row["col_30"];
  delete row["col_31"];

  // Kế thừa Chủ đề phễu
  const currentFunnel = getFunnelTopic(row);
  if (currentFunnel !== "") {
    lastValidData["Chủ đề phễu"] = currentFunnel;
    row["Chủ đề phễu"] = currentFunnel;
  } else if (lastValidData["Chủ đề phễu"]) {
    row["Chủ đề phễu"] = lastValidData["Chủ đề phễu"];
  }

  // Đồng bộ Văn phong
  const vpVal = row["Văn phong"] || row["Văn phong & Giọng điệu"] || "";
  row["Văn phong"] = vpVal;
  row["Văn phong & Giọng điệu"] = vpVal;
}

// --- PASS 2: BACKWARD FILL (Lấp ngược từ dưới lên cho các ô đầu cụm gộp bị trống) ---
let nextValidData = {};
for (let i = rows.length - 1; i >= 0; i--) {
  const row = rows[i];

  MASTER_FIELDS.forEach(field => {
    const val = row[field];
    if (isValidDataValue(val)) {
      nextValidData[field] = String(val).trim();
    } else if (!val && nextValidData[field]) {
      row[field] = nextValidData[field];
    }
  });

  const currentFunnel = row["Chủ đề phễu"];
  if (isValidDataValue(currentFunnel)) {
    nextValidData["Chủ đề phễu"] = String(currentFunnel).trim();
  } else if (!currentFunnel && nextValidData["Chủ đề phễu"]) {
    row["Chủ đề phễu"] = nextValidData["Chủ đề phễu"];
  }

  // Đồng bộ lại Văn phong
  const vpVal = row["Văn phong"] || row["Văn phong & Giọng điệu"] || "";
  row["Văn phong"] = vpVal;
  row["Văn phong & Giọng điệu"] = vpVal;
}

// --- 4. LỌC ĐÚNG DÒNG THEO YÊU CẦU (NẾU CÓ TARGET_ROW TỪ WEBHOOK) ---
let targetRow = null;
try {
  const webhookNode = $('Webhook - Tạo Content');
  if (webhookNode && webhookNode.first()) {
    const wb = webhookNode.first().json;
    const rawTarget = wb?.body?.target_row || wb?.query?.target_row || wb?.target_row;
    if (rawTarget !== undefined && rawTarget !== null && String(rawTarget).trim() !== "") {
      targetRow = parseInt(rawTarget);
    }
  }
} catch (e) {
  // Chạy thủ công từ nút "Tạo Content", không có Webhook
}

if (targetRow && !isNaN(targetRow)) {
  const matched = rows.find(r => parseInt(r.row_number) === targetRow);
  if (matched) {
    matched["Trạng Thái"] = "gen_options";
    return [{ json: matched }];
  }
  return [];
}

return rows.map(r => ({ json: r }));

// Node: Lấy Option được chọn + Format Nội Dung + Lấy Folder ID Kho Media Drive
return $input.all().map((item, index) => {
  // 1. Luôn lấy dữ liệu bài viết gốc từ node Lặp từng bài (tránh bị mất trường)
  const row = $('Lặp từng bài đã có content')?.item?.json || item.json || {};
  const rowId = row["row_number"] || row["ID"] || (index + 1);
  const keys = Object.keys(row);

  // Hàm trợ giúp tìm tên cột linh hoạt (tránh lỗi viết hoa/thường hoặc thừa dấu cách)
  const findKey = (needle, fallback) =>
    keys.find(k => k.trim().toLowerCase() === needle) ||
    keys.find(k => k.trim().toLowerCase().includes(needle)) || fallback;

  const keyOp1      = findKey("option 1", "Option 1");
  const keyOp2      = findKey("option 2", "Option 2");
  const keyOp3      = findKey("option 3", "Option 3");
  const keyDuyetOp  = findKey("duyệt option", "Duyệt Option");

  // Link Kho Media chứa ảnh thô đầu vào của Marketing
  const keyKhoMedia = findKey("kho media drive", "") || findKey("kho media", "") || findKey("ảnh demo", "Ảnh Demo");

  const rawSelectedOp = String(row[keyDuyetOp] || "").trim();
  if (!rawSelectedOp) {
    return { json: {
      ID: rowId,
      row_number: rowId,
      selectedOp: "CHƯA_CHỌN",
      folder_id: "",
      fullMessage: "⚠️ CHƯA CHỌN OPTION Ở CỘT 'Duyệt Option'",
      "Kết quả": "no_option_selected_error"
    } };
  }

  // Xác định người dùng chọn Option 1, 2 hay 3
  let optNum = 1;
  if (rawSelectedOp.includes("2")) optNum = 2;
  else if (rawSelectedOp.includes("3")) optNum = 3;

  const textByOpt = { 1: row[keyOp1], 2: row[keyOp2], 3: row[keyOp3] };
  let cleaned = String(textByOpt[optNum] || "")
    .replace(/🖼️\s*(MẪU\s*\d+|PREVIEW\s*ÁNH)\s*:\s*\S+/gi, "")
    .replace(/^\[.*?\]\s*/, "")
    .replace(/^📌\s*HOOK\s*:\s*/gim, "")
    .replace(/^📝\s*NỘI DUNG\s*:\s*/gim, "")
    .replace(/👉\s*Chi tiết tại:[\s\S]*$/i, "")
    .trim();

  // Bóc tách Hashtags ở cuối bài
  const hashtagRegex = /((?:#[\wÀ-ɏḀ-ỿ]+\s*)+)$/i;
  const m = cleaned.match(hashtagRegex);
  let mainText = cleaned, hashtags = "";
  if (m) { 
    hashtags = m[1].trim(); 
    mainText = cleaned.slice(0, m.index).trim(); 
  }

  let fullMessage = mainText;
  if (hashtags) fullMessage += `\n\n${hashtags}`;
  fullMessage = fullMessage.replace(/\n{3,}/g, "\n\n").trim();

  // Bóc tách Folder ID từ đường link Kho Media ảnh thô
  const rawFolder = String(row[keyKhoMedia] || "").trim();
  const fm = rawFolder.match(/folders\/([a-zA-Z0-9_-]{20,})/)
          || rawFolder.match(/[?&]id=([a-zA-Z0-9_-]{20,})/);
  const rawMediaFolderId = fm ? fm[1]
                              : (/^[a-zA-Z0-9_-]{20,}$/.test(rawFolder) ? rawFolder : "");

  // Lấy ID Folder thành phẩm Bai_Viet_Row_{id} đã được xử lý ở cụm dưới
  let outputFolderId = "";
  try {
    outputFolderId = 
      ($('Nếu chưa có thì tạo mới Folder')?.isExecuted ? $('Nếu chưa có thì tạo mới Folder').item.json.id : null) ||
      ($('Tìm Folder tương ứng với Row')?.isExecuted ? $('Tìm Folder tương ứng với Row').item.json.id : null) ||
      ($('Tìm Folder với Id đang có')?.isExecuted ? $('Tìm Folder với Id đang có').item.json.id : null) ||
      String(row['Media sẽ đăng'] || '').split('/folders/')[1] || "";
  } catch (e) {}

  return { 
    json: {
      ...row,
      ID: rowId,
      row_number: rowId,
      selectedOp: rawSelectedOp,
      selectedContent: mainText,
      folder_id: rawMediaFolderId,            // ID folder chứa ảnh thô (để quét ảnh)
      raw_media_folder_id: rawMediaFolderId,  // ID folder chứa ảnh thô
      output_folder_id: outputFolderId,        // ID folder thành phẩm Bai_Viet_Row
      fullMessage,
      "Kết quả": rawMediaFolderId ? "ready_to_gen_images" : "ready_to_gen_images_no_folder"
    } 
  };
});

