// Node: Tách ảnh từ nhiều link (Đã bổ sung mảng 2 ảnh, Style & rich_content)

const rawOutput = $input.first()?.json?.output 
  || $input.first()?.json?.text 
  || $('AI Tự chọn ảnh').first()?.json?.output 
  || "";

const cleanJson = String(rawOutput)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsedData = {};
try {
  parsedData = JSON.parse(cleanJson);
} catch (e) {
  parsedData = {};
}

function getDirectUrl(fileId) {
  if (!fileId) return "";
  const match = String(fileId).match(/\/d\/([a-zA-Z0-9_-]+)|id=([a-zA-Z0-9_-]+)/);
  const cleanId = match ? (match[1] || match[2]) : fileId;
  return `https://drive.usercontent.google.com/download?id=${cleanId}&export=download`;
}

function toArray(val) {
  if (Array.isArray(val)) return val;
  if (val === undefined || val === null || val === "") return [];
  return [val];
}

// 1. LẤY MẢNG CÁC SLIDE VÀ THÔNG SỐ STYLE TỔNG
const selectedOpStr = parsedData.selectedOp || "Option 1";
const selectedStyle = parsedData.selected_style || "";
const styleSpec     = parsedData.style_spec || "";
const styleReason   = parsedData.style_reason || "";
const totalImages   = parsedData.total_images || 1;

const items = parsedData.items 
  || parsedData.selected_media 
  || parsedData.slides 
  || parsedData.option_1 
  || [];

// 2. LẤY THÔNG TIN THƯ MỤC DRIVE BÀI VIẾT
let driveFolderId = "";
try { driveFolderId = $('Tạo Folder Ảnh Cho Bài Viết1').first()?.json?.id || $('Search files and folders1').first()?.json?.id || ""; } catch (e) {}

let driveFolderLink = "";
try { driveFolderLink = $('Tạo Folder Ảnh Cho Bài Viết1').first()?.json?.webViewLink || $('Search files and folders1').first()?.json?.webViewLink || ""; } catch (e) {}
if (!driveFolderLink && driveFolderId) {
  driveFolderLink = `https://drive.google.com/drive/folders/${driveFolderId}`;
}

const resultItems = [];

// 3. LẶP QUA TỪNG SLIDE VÀ XUẤT RA DỮ LIỆU ĐẦY ĐỦ CHO CÁC NODE SAU
if (Array.isArray(items) && items.length > 0) {
  items.forEach((item, itemIdx) => {
    const rawIds    = toArray(item.raw_image_ids   || item.raw_image_id   || item.file_id);
    const rawNames  = toArray(item.raw_image_names || item.raw_image_name || item.file_name);
    const subLabels = toArray(item.sub_labels);

    const rawImages = rawIds.map((id, i) => ({
      id: id || "",
      name: rawNames[i] || "",
      url: getDirectUrl(id)
    }));

    resultItems.push({
      json: {
        slide_index: item.variant_no || item.slide_index || (itemIdx + 1),
        total_images: totalImages,
        selectedOp: selectedOpStr,

        // Thông số Style chốt sẵn
        selected_style: selectedStyle,
        style_spec: styleSpec,
        style_reason: styleReason,

        // 🟢 TRUYỀN ĐỦ MẢNG NHIỀU ẢNH SANG NODE VISUAL BRIEF VÀ TẢI BINARY:
        raw_image_ids:   rawIds,
        raw_image_names: rawNames,
        raw_images:      rawImages,
        raw_image_count: rawImages.length,

        // Biến đại diện cho ảnh chính đầu tiên (phục vụ ghi báo cáo Sheet)
        raw_image_1_id:   rawImages[0]?.id   || "",
        raw_image_1_name: rawImages[0]?.name || "",
        raw_image_1_url:  rawImages[0]?.url  || "",

        // Nội dung chữ & Bố cục
        headline: item.headline || "",
        subtext: item.subtext || item.match_reason || "",
        content_type: item.content_type || "",
        rich_content: item.rich_content || {},
        sub_labels: subLabels,
        template_hint: item.template_hint || "",
        footnote: item.footnote || "",
        layout_note: item.layout_note || "",

        // Thư mục Drive
        drive_folder_id: driveFolderId,
        drive_folder_link: driveFolderLink
      }
    });
  });
}

return resultItems.length > 0 ? resultItems : [{ json: { error: "Không tìm thấy dữ liệu slide từ node AI Tự chọn ảnh" } }];

// Node: Gom Ảnh & Dựng Bài (Chuẩn Đa Kênh: FB Page, FB Group, TikTok)
const inputItems = $input.all();

// 1. Lấy thông tin bài viết của vòng lặp hiện tại:
let opt = null;

// Ưu tiên 1: Lấy trực tiếp từ node 'Phân loại Media' (nằm trong Loop, luôn chứa đúng bài của vòng lặp này)
try {
  const pl = $('Phân loại Media').first()?.json;
  if (pl && pl.fullMessage) opt = pl;
} catch (e) {}

// Ưu tiên 2: Nếu $input có mang fullMessage (ví dụ nhánh không media từ Phân loại Media nối thẳng qua)
if (!opt) {
  const contentInInput = inputItems.find(i => i.json?.fullMessage);
  if (contentInInput) opt = contentInInput.json;
}

// Ưu tiên 3: Lấy từ 'Loop Over Items1'
if (!opt) {
  try {
    const loopItem = $('Loop Over Items1').first()?.json;
    if (loopItem && loopItem.fullMessage) opt = loopItem;
  } catch (e) {}
}

// Ưu tiên 4 (Fallback an toàn): Đối chiếu ID với danh sách gốc 'Lấy Option content, đã có thời gian đăng'
if (!opt) {
  try {
    const allContent = $('Lấy Option content, đã có thời gian đăng').all();
    const currentId = inputItems[0]?.json?.ID || inputItems[0]?.json?.row_number;
    if (currentId) {
      const match = allContent.find(i => 
        String(i.json?.ID) === String(currentId) ||
        String(i.json?.row_number) === String(currentId)
      );
      if (match) opt = match.json;
    }
  } catch (e) {}
}

if (!opt?.fullMessage) {
  throw new Error('Không tìm được content cho bài hiện tại trong vòng lặp!');
}

const targetChannel = String(opt.targetChannel || "Facebook").trim();
const channelLower = targetChannel.toLowerCase();

// 🎯 2. Phân loại kênh thông minh:
const isAll = channelLower.includes("all") || channelLower.includes("tất cả");
const isFacebookGroup = isAll || channelLower.includes("group") || channelLower.includes("nhóm");
const isFacebook = isAll || channelLower.includes("page") || channelLower.includes("fanpage") || (channelLower.includes("facebook") && !channelLower.includes("group"));
const isTikTok = isAll || channelLower.includes("tiktok") || channelLower.includes("tik tok");

// 3. Gom danh sách Facebook Photo IDs (Sắp xếp theo tên file để Graph API cũng đúng thứ tự)
const sortedInputItems = inputItems.slice().sort((a, b) => {
  const nameA = String(a.json?.name || a.json?.title || "");
  const nameB = String(b.json?.name || b.json?.title || "");
  return nameA.localeCompare(nameB, undefined, { numeric: true, sensitivity: "base" });
});

const photoIds = sortedInputItems
  .map(i => (i.json || {}).id)
  .filter(id => id && !String(id).startsWith('http') && String(id) !== String(opt.ID));

const body = { message: opt.fullMessage || "" };
if (photoIds.length > 0) {
  body.attached_media = photoIds.map(id => ({ media_fbid: String(id) }));
}

// 4. Lấy link ảnh từ Google Drive cho Buffer (TỰ ĐỘNG SẮP XẾP CHUẨN: slide_1 -> slide_2 -> slide_3)
let driveImageUrls = [];
try {
  if ($('Lấy link Media').isExecuted) {
    const mediaItems = $('Lấy link Media').all().slice();

    // 🌟 Lọc bỏ các item rỗng/không có file ID (tránh lỗi id=undefined)
    const validMedia = mediaItems.filter(i => i.json && i.json.id && String(i.json.id) !== 'undefined');

    if (validMedia.length > 0) {
      validMedia.sort((a, b) => {
        const nameA = String(a.json?.name || "");
        const nameB = String(b.json?.name || "");
        return nameA.localeCompare(nameB, undefined, { numeric: true, sensitivity: "base" });
      });

      driveImageUrls = validMedia.map(i => 'https://drive.google.com/uc?export=download&id=' + i.json.id);
    }
  } 

  if (driveImageUrls.length === 0 && opt.directUrls && opt.directUrls.length > 0) {
    driveImageUrls = opt.directUrls.slice().sort((a, b) => 
      String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: "base" })
    );
  }
} catch (e) {}

// Kiểm tra nếu là đăng TikTok hoặc FB Group mà không có file ảnh hợp lệ nào trong Drive
if ((isTikTok || isFacebookGroup) && driveImageUrls.length === 0 && photoIds.length === 0) {
  throw new Error("Thư mục Google Drive ở cột 'Media sẽ đăng' (Cột AC) không chứa file ảnh nào! Vui lòng tải ảnh vào thư mục Drive hoặc kiểm tra lại đường dẫn.");
}

// 5. Trả ra dữ liệu chuẩn cho các nhánh sau
return [{
  json: {
    ID: opt.ID,
    selectedOp: opt.selectedOp,
    targetChannel,
    isFacebook,          // true: Fanpage
    isFacebookGroup,     // true: Facebook Group
    isTikTok,            // true: TikTok
    photo_count: driveImageUrls.length || photoIds.length,
    fb_body: body,
    fb_group_image_urls: driveImageUrls, // Mảng ảnh đã được xếp chuẩn 1 -> 2 -> 3
    tiktok_image_urls: driveImageUrls,   // Mảng ảnh đã được xếp chuẩn 1 -> 2 -> 3
    fullMessage: opt.fullMessage || "",
    scheduled_time: opt.scheduled_time || ""
  }
}];

// Node: Xóa Metadata AI (Hỗ trợ lặp và xử lý TOÀN BỘ N ảnh)
const items = $input.all();
const result = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const binaryPropName = 'data';

  // Nếu item không chứa file nhị phân ảnh thì giữ nguyên
  if (!item.binary || !item.binary[binaryPropName]) {
    result.push(item);
    continue;
  }

  // Lấy buffer của từng ảnh theo chỉ số index
  const buf = await this.helpers.getBinaryDataBuffer(index, binaryPropName);

  // Lọc xóa toàn bộ khối Exif / C2PA nhãn AI trong JPEG
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    const cleaned = [0xFF, 0xD8];
    let i = 2;
    while (i < buf.length) {
      if (buf[i] === 0xFF) {
        const marker = buf[i + 1];
        if (marker === 0xDA) { // SOS - Start of Scan (bắt đầu dữ liệu ảnh thực)
          for (let j = i; j < buf.length; j++) cleaned.push(buf[j]);
          break;
        }
        if (marker >= 0xE0 && marker <= 0xEF) { // APP0-APP15 (Khối chứa nhãn AI & Exif)
          const len = (buf[i + 2] << 8) + buf[i + 3];
          i += 2 + len;
          continue;
        }
      }
      cleaned.push(buf[i]);
      i++;
    }

    const cleanBinary = await this.helpers.prepareBinaryData(
      Buffer.from(cleaned),
      item.binary[binaryPropName].fileName || `cleaned_${index}.jpg`,
      'image/jpeg'
    );
    result.push({ json: item.json, binary: { [binaryPropName]: cleanBinary } });
  } else {
    result.push(item);
  }
}

// Trả về đủ mảng tất cả N ảnh đã được làm sạch
return result;

// 0. LẤY SỐ DÒNG CHỈ ĐỊNH TỪ WEB (NẾU CÓ BẤM TỪ WEB)
let targetRow = null;
try {
  const wb = $('Webhook Đăng Bài')?.first()?.json;
  targetRow = wb?.body?.target_row || wb?.target_row || wb?.query?.target_row || null;
} catch (e) {
  targetRow = null;
}

const skippedPastDue = [];
const passed = $input.all().map((item, index) => {
  const row = item.json;
  const rowId = Number(row["row_number"] || row["ID"] || (index + 5));
  const keys = Object.keys(row);

  // 👉 Nếu có chỉ định dòng từ web thì chỉ chạy đúng dòng đó
  if (targetRow && Number(rowId) !== Number(targetRow)) {
    return null;
  }

  const findKey = (needle, fallback) =>
    keys.find(k => k.trim().toLowerCase() === needle) ||
    keys.find(k => k.trim().toLowerCase().includes(needle)) || fallback;

  const keyOp1        = findKey("option 1", "Option 1");
  const keyOp2        = findKey("option 2", "Option 2");
  const keyOp3        = findKey("option 3", "Option 3");
  const keyDuyetOp    = findKey("duyệt option", "Duyệt Option");
  const keyStatus     = findKey("trạng thái", "Trạng Thái");
  const keyAnhDemo    = findKey("media sẽ đăng", "Media sẽ đăng");
  const keyTimePublish= findKey("thời gian đăng", "Thời Gian Đăng");
  const keyChannel    = findKey("kênh triển khai", "Kênh triển khai");

  const rawSelectedOp  = String(row[keyDuyetOp] || "").trim();
  const currentStatus   = String(row[keyStatus] || "").trim().toLowerCase();
  const rawPublishTime  = String(row[keyTimePublish] || "").trim();
  const targetChannel   = String(row[keyChannel] || "Facebook").trim();

  // 1. Chỉ lọc bỏ bài chưa duyệt Option hoặc bài đã có trạng thái posted
  if (!rawSelectedOp || currentStatus === "posted") {
    return null; 
  }

  // 1b. Khi KHÔNG chỉ định dòng cụ thể (schedule / batch toàn bộ): chỉ chạy các dòng
  // SẴN SÀNG ĐĂNG. Tránh quét nhầm draft/waiting_review/gen_* -> đăng trùng, đăng loạn.
  // (Khi có targetRow explícito từ UI thì vẫn cho chạy để user ép đăng lại.)
  if (!targetRow && currentStatus !== "publish") {
    return null;
  }

  // 1c. Giờ hẹn đã qua (Buffer từ chối) -> bỏ qua, gom sang output 2 để báo user qua cột lỗi.
  // Giờ Sheet là giờ VN: parse tường minh +07:00 (container n8n chạy UTC, parse trần lệch 7h).
  if (rawPublishTime) {
    // Sheet hay rut gon so 0 (2026-09-10 7:00) -> pad tay roi neo +07:00 (gio VN).
    // Container n8n chay UTC nen tuyet doi khong parse tran (lech 7h).
    const s = String(rawPublishTime).trim();
    const pad2n = (v) => String(v).padStart(2, "0");
    const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/);
    let t = NaN;
    if (m) t = Date.parse(`${m[1]}-${pad2n(m[2])}-${pad2n(m[3])}T${pad2n(m[4])}:${m[5]}:${m[6] || "00"}+07:00`);
    else if (/([Zz]|[+-]\d{2}:?\d{2})$/.test(s)) { const d = new Date(s); if (!isNaN(d.getTime())) t = d.getTime(); }
    if (!isNaN(t) && t <= Date.now()) {
      skippedPastDue.push({ json: {
        row_number: rowId,
        scheduled_time: rawPublishTime,
        skip_reason: `Giờ đăng ${rawPublishTime} đã qua — đặt giờ mới trong tương lai rồi đăng lại!`
      } });
      return null;
    }
  }

  // 2. Phân loại loại Link Media (Drive hay Direct Link URL)
  const rawMedia = String(row[keyAnhDemo] || "").trim();
  let mediaType = "none";
  let folderId = "";
  let directUrls = [];

  if (rawMedia) {
    if (rawMedia.startsWith("http://") || rawMedia.startsWith("https://")) {
      if (!rawMedia.includes("drive.google.com")) {
        mediaType = "direct_url";
        directUrls = rawMedia.split(/[\n,]/).map(u => u.trim()).filter(u => u.startsWith("http"));
      } else {
        mediaType = "drive";
        const fm = rawMedia.match(/folders\/([a-zA-Z0-9_-]{20,})/) || rawMedia.match(/[?&]id=([a-zA-Z0-9_-]{20,})/);
        folderId = fm ? fm[1] : "";
      }
    } else if (/^[a-zA-Z0-9_-]{20,}$/.test(rawMedia)) {
      mediaType = "drive";
      folderId = rawMedia;
    }
  }

  // 3. Trích xuất nội dung Option đã chọn
  let optNum = 1;
  if (rawSelectedOp.includes("2")) optNum = 2;
  else if (rawSelectedOp.includes("3")) optNum = 3;

  const textByOpt = { 1: row[keyOp1], 2: row[keyOp2], 3: row[keyOp3] };
  let fullMessage = String(textByOpt[optNum] || "")
    .replace(/🖼️\s*(MẪU\s*\d+|PREVIEW\s*ÁNH)\s*:\s*\S+/gi, "")
    .replace(/^\[.*?\]\s*/, "")
    .replace(/^📌\s*HOOK\s*:\s*/gim, "")
    .replace(/^📝\s*NỘI DUNG\s*:\s*/gim, "")
    .replace(/👉\s*Chi tiết tại:[\s\S]*$/i, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  return { 
    json: { 
      ID: rowId, 
      selectedOp: rawSelectedOp, 
      targetChannel, 
      mediaType, 
      folder_id: folderId, 
      directUrls, 
      fullMessage,
      scheduled_time: rawPublishTime // Vẫn giữ trường này để truyền sang Buffer lên lịch
    },
    pairedItem: { item: index } // Giữ liên kết item tránh lỗi 'Paired item data unavailable'
  };
}).filter(Boolean);
return [passed, skippedPastDue];

const items = $input.all().filter(item => item.json && item.json.id);

if (items.length === 0) {
  return [{ 
    json: { 
      hasMedia: false, 
      soLuongMedia: 0, 
      isImage: false, 
      isVideo: false 
    } 
  }];
}

// 1. Tự động quét xem trong danh sách có file Video không
const hasVideo = items.some(item => {
  const m = (item.json.mimeType || '').toLowerCase();
  const n = (item.json.name || '').toLowerCase();
  return m.startsWith('video/') || /\.(mp4|mov|avi|mkv|webm|flv)$/i.test(n);
});

// 2. Giữ nguyên vẹn 100% thông tin từng file (id, name, mimeType) + gắn cờ phân loại
return items.map(item => ({
  json: {
    ...item.json,
