}));

const items = $input.all();
const videoExts = ['.mp4', '.mov', '.avi', '.mkv', '.webm'];

// 1. Lọc tất cả các file là Video theo đuôi mở rộng
let videoItems = items.filter(i => {
  const name = (i.json.name || '').toLowerCase();
  return videoExts.some(ext => name.endsWith(ext));
});

// 2. Nếu có video chưa đăng, ưu tiên lấy các video chưa có đuôi _posted.
// Nếu tất cả đều đã có đuôi _posted (đang test lại), vẫn giữ nguyên toàn bộ để AI chọn.
const unpostedVideos = videoItems.filter(i => !/_posted\.[a-z0-9]+$/i.test(i.json.name || ''));
if (unpostedVideos.length > 0) {
  videoItems = unpostedVideos;
}

const videoCount = videoItems.length;

// 3. Nếu chỉ có đúng 1 video duy nhất -> Bỏ qua AI (skipAI = true)
if (videoCount <= 1) {
  return (videoCount ? videoItems : items).map(item => ({
    json: { ...item.json, skipAI: true }
  }));
}

// 4. Nếu có từ 2 video trở lên -> Chuyển qua AI chọn thumbnail (skipAI = false)
return [{
  json: {
    skipAI: false,
    videoCount,
    videoItems: videoItems.map(item => item.json)
  }
}];

const items = $input.all();
