const raw = $json.content.parts[0].text;
const match = raw.match(/\{[\s\S]*\}/);
const parsed = JSON.parse(match[0]);

function sanitize(name) {
  return name.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]/g, '-').replace(/-+/g, '-');
}

return parsed.videos.map(v => {
  const isSelected = v.id === parsed.selected_video_id;
  let finalName = sanitize(v.new_file_name);
  return {
    json: { id: v.id, new_file_name: finalName, isSelected }
  };
});

const items = $input.all();

// 1. Lấy thông tin bài viết của vòng lặp hiện tại:
let opt = {};
// Ưu tiên 1: Lấy trực tiếp từ node 'Phân loại Media' (nằm trong Loop, đúng bài của vòng lặp hiện tại)
try {
  const pl = $('Phân loại Media').first()?.json;
  if (pl && pl.fullMessage) opt = pl;
} catch (e) {}

// Ưu tiên 2: Fallback lấy từ 'Loop Over Items1'
if (!opt.fullMessage) {
  try {
    const loopItem = $('Loop Over Items1').first()?.json;
    if (loopItem && loopItem.fullMessage) opt = loopItem;
  } catch (e) {}
}

// Ưu tiên 3: Fallback lấy từ node ngoài loop (khi test đơn)
if (!opt.fullMessage) {
  try {
    opt = $('Lấy Option content, đã có thời gian đăng').first().json;
  } catch (e) {}
}

const targetChannel = String(opt.targetChannel || "Facebook").trim();
const channelLower = targetChannel.toLowerCase();

// 🎯 Phân loại kênh thông minh (Hỗ trợ: Facebook Page, Facebook Group, TikTok, All):
const isAll = channelLower.includes("all") || channelLower.includes("tất cả");
const isFacebookGroup = isAll || channelLower.includes("group") || channelLower.includes("nhóm");
const isFacebook = isAll || channelLower.includes("page") || channelLower.includes("fanpage") || (channelLower.includes("facebook") && !channelLower.includes("group"));
const isTikTok = isAll || channelLower.includes("tiktok") || channelLower.includes("tik tok");

// Trường hợp nhiều video (qua AI Chọn):
let selectedId = null;
let originalInfo = null;
try {
  const selectedObj = $('Parse & Làm Sạch Tên').all().find(i => i.json.isSelected);
  if (selectedObj) {
    selectedId = selectedObj.json.id;
    originalInfo = $('Đếm & Kiểm Tra Nhiều Video').first().json.videoItems.find(v => v.id === selectedId);
  }
} catch (e) {}

// Trường hợp 1 video (bỏ qua AI) hoặc đã chọn:
const selectedItem = (selectedId ? items.find(i => i.json.id === selectedId) : items[0]) || items[0];

return [{
  json: {
    id: selectedItem?.json?.id || items[0]?.json?.id,
    name: selectedItem?.json?.name || items[0]?.json?.name,
    mimeType: originalInfo ? originalInfo.mimeType : (selectedItem?.json?.mimeType || 'video/mp4'),
    targetChannel,
    isFacebook,          // Đăng Fanpage
    isFacebookGroup,     // Đăng Facebook Group
    isTikTok,            // Đăng TikTok
    folder_id: opt.folder_id || "",
    fullMessage: opt.fullMessage || "",
    scheduled_time: opt.scheduled_time || ""
  }
}];

// Node: VISUAL BRIEF BUILDER (Bảo toàn 3 Items & Giữ nguyên Binary)

// 1. Đọc dữ liệu Brand Rules từ Google Sheet
let sheetItem = {};
try {
  sheetItem = $('Lặp từng bài đã có content').first().json;
} catch (e1) {
  try {
    sheetItem = $('Xử lý gom các nội dung trùng').first().json;
  } catch (e2) {
    sheetItem = $('Get row(s) in sheet1').first()?.json || $input.first()?.json || {};
  }
}

function getRawCellContent(obj, keywords) {
  if (!obj) return "";
  const keys = Object.keys(obj);
  for (const kw of keywords) {
    const cleanKw = kw.toLowerCase().replace(/\s+/g, '');
    for (const k of keys) {
      if (k.toLowerCase().replace(/\s+/g, '').includes(cleanKw)) {
        if (obj[k] !== undefined && obj[k] !== null) return String(obj[k]).trim();
      }
    }
  }
  return "";
}

const brandRules = {
  design_rule:       getRawCellContent(sheetItem, ["thiếtkếảnh", "designrule", "bốcục"]),
  background_rule:   getRawCellContent(sheetItem, ["background", "mềnnền"]),
  footer_badge_rule: getRawCellContent(sheetItem, ["bagde", "badge", "footer"])
};

// 2. Đọc dữ liệu Master từ AI Tự Chọn Ảnh
let aiRoot = {};
try {
  const rawText = $('AI Tự chọn ảnh').first()?.json?.output || $('AI Tự chọn ảnh').first()?.json?.text || "";
  const cleanJson = String(rawText).replace(/```json/gi, '').replace(/```/g, '').trim();
  aiRoot = JSON.parse(cleanJson);
} catch (e) {
  aiRoot = $input.first()?.json || {};
}

// 3. Trả về đúng N Items tương ứng với N Slide (BẢO TOÀN BINARY)
return $input.all().map((item, index) => {
  const j = item.json || {};

  return {
    json: {
      slide_index:     j.slide_index || j.variant_no || (index + 1),
      total_images:    aiRoot.total_images || $input.all().length,
      selectedOp:      aiRoot.selectedOp || j.selectedOp || "",
      selected_style:  aiRoot.selected_style || j.selected_style || "",
      style_spec:      aiRoot.style_spec || j.style_spec || "",
      style_reason:    aiRoot.style_reason || j.style_reason || "",

      // Bộ quy tắc đồ họa
      brand_rules:     brandRules,

      // Dữ liệu nội dung Slide
      headline:        j.headline || "",
      subtext:         j.subtext || "",
      content_type:    j.content_type || "",
      rich_content:    j.rich_content || {},
      template_hint:   j.template_hint || "",
      layout_note:     j.layout_note || "",
      raw_image_ids:   j.raw_image_ids || (j.raw_image_1_id ? [j.raw_image_1_id] : []),
      raw_image_names: j.raw_image_names || (j.raw_image_1_name ? [j.raw_image_1_name] : []),
      raw_image_1_url: j.raw_image_1_url || ""
    },
    // 🟢 RẤT QUAN TRỌNG: Giữ lại Binary từ node Tải Ảnh truyền sang
    binary: item.binary || {}
  };
});

// Node: Code chuẩn hóa 3 Options (Tương thích OpenAI gpt-4o-mini, Gemini, Groq & Claude)
const items = $input.all();

// ---- Helper: cố gắng parse 1 string thành JSON, có dọn code-fence ----
function tryParseJSON(str) {
  if (typeof str !== 'string') return null;
  const cleaned = str
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}

// ---- Helper: dò đệ quy trong mọi cấu trúc (object/array/string-JSON)
// để tìm object có chứa option_1 / option_2 / option_3 ----
function deepFindOptions(node, depth = 0) {
  if (!node || depth > 10) return null;

  // Nếu là string -> thử parse JSON rồi đệ quy tiếp
  if (typeof node === 'string') {
    const parsed = tryParseJSON(node);
    return parsed ? deepFindOptions(parsed, depth + 1) : null;
  }

  if (typeof node !== 'object') return null;

  // Tìm thấy đích rồi
  if (node.option_1 || node.option_2 || node.option_3) return node;

  // Ưu tiên các key "bọc" hay gặp ở các provider (OpenAI/Gemini/Groq/Claude)
  const priorityKeys = ['text', 'content', 'message', 'output', 'candidates', 'parts'];

  if (Array.isArray(node)) {
    for (const el of node) {
      const found = deepFindOptions(el, depth + 1);
      if (found) return found;
    }
    return null;
  }

  for (const key of priorityKeys) {
    if (key in node) {
      const found = deepFindOptions(node[key], depth + 1);
      if (found) return found;
    }
  }

  // Cuối cùng mới quét toàn bộ các key còn lại (phòng trường hợp lạ)
  for (const key of Object.keys(node)) {
    if (priorityKeys.includes(key)) continue;
    const found = deepFindOptions(node[key], depth + 1);
    if (found) return found;
  }

  return null;
}

return items.map((item, index) => {
  const j = item.json;

  // 1 & 2. TÌM parsed BẰNG DEEP SEARCH (thay cho việc đoán path cứng trước đây)
  const parsed = deepFindOptions(j) || {};

  // 3. LẤY ROW_NUMBER TỪ NODE LẶP CHUẨN XÁC THEO LUẬT LẶP
  let rowId = j.row_number || j.row_id || j.id || "";

  // Thử lấy từ Node Lặp (Loop Over Items2 / Loop Over Items)
  if (!rowId) {
    try {
      rowId = $('Loop Over Items2').itemMatching(index)?.json?.row_number || "";
    } catch (e) {}
  }
  if (!rowId) {
