    const dim = readImageSize(bgBuffer);
    if (dim && dim.width > 0 && dim.height > 0) {
      bgWidth = dim.width;
      bgHeight = dim.height;
    }
  } catch (err) {
    // khong doc duoc buffer thi giu mac dinh 1080x1080 (an toan, logo van dung ty le)
  }

  // Tinh chieu rong logo theo ty le chieu rong anh, roi CHAN CUNG boi tran chieu cao —
  // neu bi tran chieu cao thi giam chieu rong lai theo dung ty le that cua file logo, de
  // logo khong bao gio to bat thuong du anh nen vuong hay bi lech ty le.
  let logo_target_width = Math.round(bgWidth * LOGO_WIDTH_RATIO);
  const logo_target_height_cap = Math.round(bgHeight * MAX_LOGO_HEIGHT_RATIO);
  if (logo_target_width / LOGO_ASPECT > logo_target_height_cap) {
    logo_target_width = Math.round(logo_target_height_cap * LOGO_ASPECT);
  }

  const logo_margin_x = Math.round(bgWidth * MARGIN_X_RATIO);
  const logo_margin_y = Math.round(bgHeight * MARGIN_Y_RATIO);

  const logoBuffer = Buffer.from(LOGO_B64, 'base64');
  const logoBinary = await this.helpers.prepareBinaryData(logoBuffer, 'ecolar-logo.png', 'image/png');

  results.push({
    json: {
      ...j,
      bg_width: bgWidth,
      bg_height: bgHeight,
      logo_target_width,
      logo_target_height_cap,
      logo_margin_x,
      logo_margin_y,
    },
    binary: {
      ...(item.binary || {}),
      logo_image: logoBinary,
    },
    pairedItem: item.pairedItem,
  });
}

return results;

