  return `TIÊU ĐỀ PHỤ — đây KHÔNG phải slide mở đầu, tiêu đề ở đây chỉ đóng vai trò 
bổ trợ, triển khai ý cho tiêu đề chính ở slide đầu tiên. BẮT BUỘC:
   - Cỡ chữ phần từ khóa chính phải NHỎ HƠN tiêu đề chính khoảng 25-35% 
     (ước tính chiếm 40-50% chiều rộng vùng nội dung, thay vì 60-70% như 
     tiêu đề chính).
   - GIỮ NGUYÊN 100% MỨC ĐỘ CHI TIẾT THỊ GIÁC so với tiêu đề chính: cùng độ 
     dày hiệu ứng nổi 3D, cùng cường độ bóng đổ mềm, cùng độ đậm viền pill, 
     cùng gradient màu. CHỈ ĐƯỢC THAY ĐỔI KÍCH THƯỚC CHỮ — TUYỆT ĐỐI KHÔNG 
     được làm phẳng, làm mờ nhạt, hay lược bớt bất kỳ hiệu ứng nào để "cho 
     gọn" hay "phù hợp với chữ nhỏ hơn". Tưởng tượng đây là tiêu đề chính 
     được thu nhỏ lại bằng công cụ scale — không phải vẽ lại từ đầu ở mức 
     đơn giản hơn.
   - Cùng font (Nunito Sans), cùng kiểu pill bo tròn, cùng vị trí căn lề, 
     cùng tông màu với tiêu đề chính — để khi ghép các slide phụ với nhau, 
     người xem thấy chúng "cùng một họ", đồng nhất định dạng với nhau.
   - KHÔNG được to bằng hoặc to hơn tiêu đề chính, dù chỉ 1 chữ.`;
}

// 🔹 Ước lượng độ rộng khung nội dung dựa trên dữ liệu THẬT của từng slide
// (thay vì gán cứng 1 tỉ lệ cho mọi slide) — đây là phần làm cho zone "linh hoạt"
function estimateContentWidthRatio(slide, isMainSlide) {
  const contentType = slide.content_type || "tagline";

  // Tỉ lệ nền theo LOẠI nội dung — list/icon_grid cần khung rộng hơn vì có
  // icon + chữ nằm ngang, còn tagline chỉ 1 dòng ngắn nên cần ít chỗ hơn.
  const BASE_RATIO = {
    tagline: 0.30,
    paragraph: 0.38,
    list: 0.44,
    icon_grid: 0.46,
  };
  let ratio = BASE_RATIO[contentType] ?? 0.40;

  // Headline dài hơn → cần rộng hơn một chút, đặc biệt ở slide chính vì chữ to hơn
  const headlineWords = (slide.headline || "").trim().split(/\s+/).filter(Boolean).length;
  if (isMainSlide && headlineWords >= 7) ratio += 0.04;
  else if (!isMainSlide && headlineWords >= 6) ratio += 0.02;

  // Đo độ dài từng dòng rich_content thật (không đoán, đếm số từ thật)
  const rc = slide.rich_content || {};
  let maxLineWords = 0;
  const countLine = (text) => {
    const words = String(text || "").replace(/\*\*/g, "").trim().split(/\s+/).filter(Boolean);
    if (words.length) maxLineWords = Math.max(maxLineWords, words.length);
  };
  if (contentType === "tagline") countLine(rc.tagline_text);
  if (contentType === "paragraph") countLine(rc.paragraph_text);
  if (contentType === "list" && Array.isArray(rc.list_items)) rc.list_items.forEach(countLine);
  if (contentType === "icon_grid" && Array.isArray(rc.grid_items)) rc.grid_items.forEach((g) => countLine(g.label));

  // Dòng dài (gần chạm ngân sách chữ tối đa) → cần khung rộng hơn để không vỡ dòng
  if (maxLineWords >= 8) ratio += 0.03;
  else if (maxLineWords > 0 && maxLineWords <= 4) ratio -= 0.02;

  // Chặn trong khoảng an toàn — không để khung nội dung nuốt hết canvas,
  // cũng không để nó co lại quá mỏng không chứa nổi chữ
  return Math.min(0.52, Math.max(0.28, ratio));
}

// 🔹 Rule ảnh gà — khôi phục cấu trúc đánh số như bản gốc (không gộp thành câu văn xuôi)
function buildImageRule(slide, brandRules, inputData, dims, isMainSlide) {
  const custom = (
    brandRules.design_rule ||
    brandRules.image_design_rules ||
    slide.image_design_rules ||
    inputData.image_design_rules ||
    ""
  ).trim();

  const EDGE_MARGIN = 50;
  const GLOW_BUFFER = 20;
  const GAP_RATIO = 0.03; // khoảng đệm giữa khung nội dung và zone ảnh gà

  const IMAGE_ZONE_TOP_RATIO = 0.16;
  const IMAGE_ZONE_BOTTOM_RATIO = 0.14;
  const MAX_SINGLE_AREA_RATIO = 0.34;

  let sizeLine;
  if (dims && dims.w && dims.h) {
    // 🔧 Tỉ lệ zone giờ được TÍNH RA từ dữ liệu slide, không còn là hằng số 0.55
    const contentWidthRatio = estimateContentWidthRatio(slide, isMainSlide);
    const imageZoneWidthRatio = Math.max(0.30, 1 - contentWidthRatio - GAP_RATIO);

    const zoneX0 = Math.round(dims.w * (1 - imageZoneWidthRatio));
    const zoneX1 = dims.w - EDGE_MARGIN;
    const zoneY0 = Math.round(dims.h * IMAGE_ZONE_TOP_RATIO);
    const zoneY1 = Math.round(dims.h * (1 - IMAGE_ZONE_BOTTOM_RATIO)) - EDGE_MARGIN;

    const zoneW = Math.max(0, zoneX1 - zoneX0);
    const zoneH = Math.max(0, zoneY1 - zoneY0);

    const capByZone = Math.max(0, Math.min(zoneW, zoneH) - 2 * GLOW_BUFFER);
    const capByArea = Math.round(Math.sqrt(dims.w * dims.h * MAX_SINGLE_AREA_RATIO));
    const maxDiameterSingle = Math.min(capByZone, capByArea);

    const maxDiameterDouble = Math.max(
      0,
      Math.min(Math.round(zoneW / 2) - GLOW_BUFFER, zoneH - 2 * GLOW_BUFFER),
    );

    sizeLine = `
  0. HỘP AN TOÀN DÀNH RIÊNG CHO ẢNH GÀ (kích thước được TÍNH RIÊNG cho slide này dựa 
theo độ dài nội dung thực tế — không phải khung cố định — đã lùi vào ${EDGE_MARGIN}px 
so với mép canvas thật):
     - Tọa độ hộp: x từ ${zoneX0}px đến ${zoneX1}px, y từ ${zoneY0}px đến ${zoneY1}px (canvas ${dims.w}x${dims.h}px).
     - TOÀN BỘ khung tròn ảnh gà (KỂ CẢ glow/viền sáng) PHẢI nằm gọn bên trong hộp này.
  1. KÍCH THƯỚC CHÍNH XÁC:
     - 1 ảnh gà: đường kính (KỂ CẢ glow) KHÔNG vượt quá ${maxDiameterSingle}px.
     - 2 ảnh gà: đường kính mỗi khung (KỂ CẢ glow) KHÔNG vượt quá ${maxDiameterDouble}px.
  2. TÂM KHUNG ẢNH: khoảng cách từ tâm đến MỌI cạnh hộp an toàn ≥ bán kính kể cả glow, luôn để dư vài pixel, không chạm sát biên.
  2.5. HÌNH DẠNG BẮT BUỘC: PHẢI là hình tròn hoàn hảo (bán kính ngang = dọc), tuyệt đối không nén thành oval.
  3. Nếu không đủ chỗ, BẮT BUỘC giảm đều đường kính, không kéo méo, không tràn hộp.`;
  } else {
    sizeLine = `
  1. KHOẢNG CÁCH MÉP: Mọi khung ảnh gà PHẢI cách mép ngoài TỐI THIỂU 50px.
  2. GIỚI HẠN KÍCH THƯỚC: Nếu 2 ảnh, đường kính mỗi ảnh KHÔNG vượt quá 40-45% chiều rộng canvas.`;
  }

  const hardRule = sizeLine + `
  5. TUYỆT ĐỐI KHÔNG để bất kỳ phần nào bị cắt xén bởi mép canvas hoặc mép hộp an toàn.`;
  return (custom ? custom + "\n" : "") + hardRule;
}

return slides.map((slide, index) => {
  const slideIndex = slide.slide_index || slide.variant_no || index + 1;
  const isMainSlide = Number(slideIndex) === 1;
  const inputItem = allInputItems[index] || allInputItems[0];
  const richContentClean = formatRichContent(
    slide.content_type,
    slide.rich_content,
  );
  const emphasisWords = collectEmphasisWords(
    slide.content_type,
    slide.rich_content,
  );
  const orientationLabel = describeOrientation(slide.layout_note);
  const cleanLayout = cleanLayoutNote(slide.layout_note, orientationLabel);

  const dims = parseDims(slide.layout_note);

  const sliceBaseImage =
    slide.panorama_slice_b64 || slide.panorama_slice_url || "";
  const rawImageIds = Array.isArray(slide.raw_image_ids)
    ? slide.raw_image_ids
    : [];
  const rawChickenImages = Array.isArray(slide.raw_images)
    ? slide.raw_images
    : slide.raw_image_1_url
      ? [slide.raw_image_1_url]
      : [];
  const rawImageNames = Array.isArray(slide.raw_image_names)
    ? slide.raw_image_names
    : [];

  const chickenImageCount =
    rawImageNames.length || rawChickenImages.length || rawImageIds.length || 0;

  const combinedRawImages = [
    ...(sliceBaseImage ? [sliceBaseImage] : []),
    ...rawChickenImages,
  ];

const imageRule = buildImageRule(slide, brandRules, inputData, dims, isMainSlide);
  const footerRule = FOOTER_RULE(brandRules.footer_badge_rule || "");

  const titleRule = buildTitleRule(isMainSlide);

  // ====== PROMPT CHẶT HƠN — OVERLAY-ONLY, NỀN ĐÃ CÓ SẴN THEO TỪNG SLIDE ======
  const promptText = `
NHIỆM VỤ: OVERLAY-ONLY EDIT cho banner thương hiệu Ecolar. Hãy coi ảnh 1 
đính kèm giống hệt một FILE PNG NỀN ĐÃ RENDER SẴN VÀ BẤT BIẾN (immutable 
background layer) — bạn không "vẽ tranh dựa trên cảm hứng từ ảnh 1", mà 
đang làm thao tác "Paste layer mới lên trên" như trong Photoshop: giữ 
nguyên 100% pixel của layer dưới, chỉ đặt thêm các layer PNG trong suốt 
(tiêu đề, khung, ảnh gà, badge) đè lên trên. Bất kỳ đường nét, họa tiết, 
đường cong nào đã có sẵn trong ảnh 1 đều là DỮ LIỆU CỐ ĐỊNH — nhiệm vụ 
của bạn là SAO CHÉP lại y hệt, không phải "vẽ theo phong cách tương tự".

CẤM TUYỆT ĐỐI (vi phạm = FAIL):
- Không tái tạo/vẽ lại/làm sáng-tối lại nền xanh.
- Không dịch chuyển, không co giãn, không đổi tỉ lệ khung ảnh.
- Không chạm vào dải 12% đáy ảnh và viền 4 cạnh (giữ nguyên y hệt pixel gốc, đặc biệt đường sóng và dải sáng).
- KHÔNG được vẽ THÊM bất kỳ đường sóng, vệt sáng, hoa văn chuyển động nào mới ngoài những gì đã có sẵn trong ảnh nền gốc — kể cả khi cho rằng nó "hợp phong cách" hay "làm đẹp thêm". Vùng nền chỉ được giữ y hệt, không được sáng tạo thêm chi tiết mới lên nó (lá bay, icon, khung chữ vẫn được phép vì đó là lớp phủ riêng biệt, không phải chi tiết của nền).
- PHÂN BIỆT RÕ 2 LOẠI LÁ (QUAN TRỌNG): Nếu ảnh 1 (nền gốc) đã có sẵn hình lá/dây leo/cành cây là HỌA TIẾT CỦA NỀN — những lá này PHẢI giữ NGUYÊN VẸN 100% vị trí, hình dạng, kích thước, KHÔNG được vẽ lại hay "làm mới" chúng dưới bất kỳ lý do gì, xử lý y hệt như xử lý dải sóng nền. TUYỆT ĐỐI KHÔNG nhầm lẫn lá có sẵn trong nền với lá trang trí được phép thêm mới ở mục "ĐƯỢC PHÉP VẼ" bên dưới — đó là 2 loại hoàn toàn khác nhau: lá trong nền = khóa cứng, lá trang trí mới quanh tiêu đề = được tự do vẽ thêm.

- KHÓA NGHIÊM NGẶT DẢI MÉP GHÉP SLIDE: Vì slide này sẽ được ghép cạnh các slide khác thành 1 bài đăng liền mạch, dải viền mỏng sát 4 cạnh canvas (khoảng 30-50px tính từ mép) là ĐIỂM NỐI QUAN TRỌNG NHẤT — bất kỳ đường sóng, vệt sáng, họa tiết nào chạm đến dải này PHẢI giữ NGUYÊN VẸN TUYỆT ĐỐI về góc độ, độ cao, và điểm cắt tại đúng vị trí mép, sai số cho phép gần như bằng 0 (khắt khe hơn cả rule "khóa tọa độ" ở vùng trung tâm) — vì chỉ cần lệch nhẹ tại đây, khi ghép cạnh slide khác sẽ lộ ngay đường gãy khúc rất rõ.

- XỬ LÝ XUNG ĐỘT KHÔNG GIAN: Nếu vùng đặt content (khung nội dung/ảnh gà) buộc phải nằm trên họa tiết lá/sóng có sẵn trong nền, KHÔNG được tự vẽ lại, nắn lại, hay tưởng tượng lại họa tiết đó ở bất kỳ mức độ nào — kể cả "vẽ mờ hơn" hay "vẽ mềm hơn". Cách xử lý DUY NHẤT được phép: đặt một lớp phủ ĐƠN SẮC bán trong suốt (overlay khối màu trắng hoặc xanh đậm, opacity 40-60%, bo góc theo khung content) NGAY PHÍA TRÊN vùng đó, giống dán một tấm kính mờ lên ảnh — họa tiết lá/sóng bên dưới lớp kính này vẫn PHẢI giữ nguyên hình dạng, vị trí, kích thước gốc, chỉ bị che bớt bởi lớp phủ ở trên, không phải bị vẽ lại. TUYỆT ĐỐI KHÔNG được "kéo dài", "nắn lại", "đồng bộ hóa" đường cong của dải sóng hay đổi kích thước/vị trí bất kỳ chiếc lá nào trong họa tiết nền cho "khớp" với bố cục mới, dù thấy hợp lý hơn — đường cong và hình lá là dữ liệu đã khóa, không tinh chỉnh.

- Không vẽ gì vào góc trên-trái (18% x 12%, vùng dành cho logo).
- KHÔNG áp bất kỳ bộ lọc màu toàn cục nào (không auto color-correct, không auto white-balance, không tăng saturation/contrast/brightness toàn ảnh). Giữ đúng mã màu, độ bão hòa, độ sáng của ảnh 1 gốc pixel-by-pixel ở mọi vùng không được liệt kê để vẽ đè lên.
- Copy y nguyên 4 góc ảnh (mỗi góc 80x80px) từ ảnh 1 — không render lại các góc này dưới bất kỳ hình thức nào.

ĐƯỢC PHÉP VẼ — chỉ trong vùng trung tâm an toàn:
1. TIÊU ĐỀ: ${titleRule}
Font Nunito Sans duy nhất, hiệu ứng chữ nổi 3D nhẹ, phần mở đầu trong pill bo tròn, từ khóa chính phóng to + bóng đổ mềm (trắng/vàng chanh). Vài lá thảo mộc xanh bay lơ lửng quanh chữ. VỊ TRÍ BẮT BUỘC: điểm bắt đầu (mép trái) của pill/tiêu đề phải cách mép trái canvas TỐI THIỂU 10% chiều rộng VÀ cách mép trên TỐI THIỂU 14% chiều cao — để không bao giờ chạm vào vùng logo 18%x12% góc trên-trái, kể cả một phần nhỏ.

2. KHUNG NỘI DUNG: bo góc, viền mỏng thanh lịch, từ khóa nhấn mạnh đổi màu vàng chanh/xanh non.
3. ẢNH GÀ THẬT (${chickenImageCount} ảnh đính kèm — dùng ĐỦ, không bỏ ảnh nào):
- QUY TẮC KÍCH THƯỚC & KHOẢNG CÁCH AN TOÀN (HARD MARGIN RULE — BẮT BUỘC):${imageRule}
4. BADGE LIÊN HỆ: ${footerRule}

NỘI DUNG SLIDE ${slideIndex}/${totalImages} (khung ảnh: ${cleanLayout}):
- Headline: "${slide.headline || ""}"
- Subtext: "${slide.subtext || ""}"
${richContentClean ? `- Chi tiết (${slide.content_type || ""}):\n- ${richContentClean}` : ""}
${emphasisWords.length ? `- Từ khoá nhấn mạnh (in đậm/đổi màu nổi bật): ${emphasisWords.join(", ")}` : ""}

BƯỚC TỰ KIỂM TRA BẮT BUỘC TRƯỚC KHI XUẤT (thực hiện tuần tự):

1. Xác định trong ảnh 1 gốc: vị trí đỉnh từng đường cong sóng, đường viền ngoài của từng chiếc lá trong họa tiết nền, vị trí cụm nhà/làng silhouette, vị trí 4 góc canvas (80x80px mỗi góc).

2. Đối chiếu ẢNH VỪA TẠO với các điểm neo trên — từng điểm phải trùng khớp gần như tuyệt đối (sai lệch cho phép < 2-3px, chỉ do resize/nén ảnh).

3. Tự hỏi: "Nếu xóa hết mọi layer content (tiêu đề, khung chữ, ảnh gà, badge) khỏi ảnh vừa tạo, phần nền còn lại có giống hệt pixel ảnh 1 không?" — Nếu câu trả lời không phải "có, giống hệt", đây là LỖI NGHIÊM TRỌNG, phải tạo lại và CHỈ đè content lên, tuyệt đối không chỉnh sửa/di chuyển/vẽ lại bất kỳ pixel nền nào, kể cả để "làm đẹp thêm" hay "cho hợp bố cục".

4. Nếu vùng content che một phần họa tiết nền, xác nhận đã dùng lớp phủ đơn sắc bán trong suốt (bước 2 phía trên) chứ không phải vẽ lại họa tiết ở độ mờ thấp hơn.

5. Với MỖI khung ảnh gà: xác định lại tọa độ hộp an toàn đã nêu ở mục 0 phần "QUY TẮC KÍCH THƯỚC & KHOẢNG CÁCH AN TOÀN" (x/y cụ thể theo canvas ${dims ? dims.w : "?"}x${dims ? dims.h : "?"}px) — đo khoảng cách từ điểm NGOÀI CÙNG của glow/viền sáng đến cả 4 cạnh CỦA HỘP AN TOÀN ĐÓ (không phải 4 cạnh canvas). Nếu bất kỳ khoảng cách nào âm (tức đã tràn ra ngoài hộp), đây là LỖI NGHIÊM TRỌNG — phải thu nhỏ khung ảnh cho đến khi nằm gọn hoàn toàn trong hộp.

6. Với dải viền 30-50px sát 4 cạnh canvas: xác nhận bất kỳ đường sóng/họa tiết nào cắt ngang dải này có góc độ, độ cao, điểm cắt khớp CHÍNH XÁC với ảnh 1 gốc tại đúng vị trí đó — vì đây là điểm sẽ ghép nối trực tiếp với slide bên cạnh khi đăng bài, sai lệch dù nhỏ cũng sẽ lộ rõ.
`.trim();

  const rawImageId = rawImageIds[0] || slide.raw_image_1_id || "";

  return {
    json: {
      slide_index: slideIndex,
      total_post_images: totalImages,
      chosen_style: selectedStyle,
      style_spec: styleSpec,
      headline: slide.headline || "",
      subtext: slide.subtext || "",
      content_type: slide.content_type || "",
      rich_content: slide.rich_content || {},
      template_hint: slide.template_hint || "",
      layout_note: slide.layout_note || "",
      raw_image_ids: rawImageIds,
      raw_image_names: rawImageNames,
      raw_images: combinedRawImages,
      raw_image_1_url: rawImageId
        ? `https://drive.google.com/thumbnail?id=${rawImageId}&sz=s1200`
        : "",
      panorama_slice_url: slide.panorama_slice_url || "",
      chicken_image_count: chickenImageCount,
