parameters.jsCode:
const inputData = $input.first()?.json || {};

const brandRules = inputData.brand_rules || {};
const selectedStyle = inputData.selected_style || "";
const styleSpec = inputData.style_spec || "";

const slides = Array.isArray(inputData.items)
  ? inputData.items
  : $input.all().map(i => i.json);

const totalSlides = slides.length;


// =====================================================
// 1. HELPER: XÁC ĐỊNH HƯỚNG ẢNH
// =====================================================
function describeOrientation(layoutNote) {
  const m = String(layoutNote || "").match(/(\d+)\s*x\s*(\d+)/i);

  if (!m) return "";

  const w = parseInt(m[1], 10);
  const h = parseInt(m[2], 10);

  if (w === h) {
    return "Khung VUÔNG (tỉ lệ 1:1)";
  }

  if (w > h) {
    return `Khung NGANG (tỉ lệ ${(w / h).toFixed(2)}:1)`;
  }

  return `Khung DỌC (tỉ lệ 1:${(h / w).toFixed(2)})`;
}


// =====================================================
// 2. LẤY KÍCH THƯỚC PLACEHOLDER
// =====================================================
function extractPlaceholderDimension(layoutNote, orientationLabel) {
  const text = String(layoutNote || "");

  const m =
    text.match(/\((\d+x\d+)px?\)/i) ||
    text.match(/^(\d+x\d+)/i);

  const dimension = m ? m[1] : "";

  return `${dimension}px${
    orientationLabel ? ` (${orientationLabel})` : ""
  }`;
}


// =====================================================
// 3. BÓC TÁCH KÍCH THƯỚC GỐC CỦA TỪNG SLIDE
// =====================================================
const slidesLayout = slides.map((slide, index) => {
  const orientationLabel = describeOrientation(slide.layout_note);

  const m = String(slide.layout_note || "")
    .match(/(\d+)\s*x\s*(\d+)/i);

  const w = m ? parseInt(m[1], 10) : 1200;
  const h = m ? parseInt(m[2], 10) : 1200;

  return {
    slide_number: index + 1,

    width: w,
    height: h,

    aspect_ratio: w / h,

    orientation:
      orientationLabel ||
      (
        w === h
          ? "VUÔNG"
          : w > h
          ? "NGANG"
          : "DỌC"
      ),

    layout_note: slide.layout_note || "",
    template_hint: slide.template_hint || ""
  };
});


// =====================================================
// 4. TÍNH MASTER PANORAMA THEO TỶ LỆ THẬT CỦA SLIDE
// =====================================================

// Chiều cao chuẩn chung của Panorama.
// Mọi slide sẽ cùng chiều cao này khi ghép vào panorama.
const MASTER_HEIGHT = 1200;

let currentX = 0;

const slideZones = slidesLayout.map((slide) => {
  const ratio = slide.width / slide.height;

  // Ví dụ:
  // 1:1 => 1200 x 1200
  // 3:2 => 1800 x 1200
  // 2:3 => 800 x 1200
  const zoneWidth = Math.round(MASTER_HEIGHT * ratio);

  const zone = {
    slide_number: slide.slide_number,

    source_width: slide.width,
    source_height: slide.height,

    aspect_ratio: ratio,

    zone_width: zoneWidth,
    zone_height: MASTER_HEIGHT,

    start_x: currentX,
    end_x: currentX + zoneWidth,

    orientation: slide.orientation,

    layout_note: slide.layout_note,
    template_hint: slide.template_hint
  };

  currentX += zoneWidth;

  return zone;
});


// =====================================================
// 5. KÍCH THƯỚC PANORAMA TỔNG
// =====================================================
const panoramaWidth = currentX;
const panoramaHeight = MASTER_HEIGHT;

const panoramaSize =
  `${panoramaWidth}x${panoramaHeight}`;

const panoramaAspectRatio =
  panoramaWidth / panoramaHeight;


// =====================================================
// 6. GHI CHÚ THIẾT KẾ
// =====================================================
const SUPPLEMENT_NOTE = `
GHI CHÚ TINH CHỈNH:
- Nền thực tế là 1 màu xanh đậm đặc thương hiệu Ecolar (#056823), có thể thêm hoạ tiết nông trại/lá cây/đường nét đồ họa mờ chìm trong nền.
- Bố cục các mảng khối đồ họa, dải màu và ánh sáng lan toả tự nhiên, liên tục và liền mạch xuyên suốt toàn bộ chiều ngang từ mép trái sang mép phải.
`.trim();


// =====================================================
// 7. TẠO MÔ TẢ TỪNG VÙNG SLIDE TRÊN PANORAMA
// =====================================================
const zoneLayouts = slideZones.map((zone, index) => {
  const slide = slides[index];

  const orientationLabel =
    describeOrientation(slide.layout_note);

  const placeholderDim =
    extractPlaceholderDimension(
      slide.layout_note,
      orientationLabel
    );

  const startPct =
    (
      (zone.start_x / panoramaWidth) *
      100
    ).toFixed(2);

  const endPct =
    (
      (zone.end_x / panoramaWidth) *
      100
    ).toFixed(2);

  const dimText = placeholderDim
    ? `
  + Chừa vùng nền tương đối sạch cho placeholder ${placeholderDim}
  + KHÔNG vẽ khung placeholder.
  + KHÔNG vẽ viền placeholder.
  + KHÔNG vẽ hình dạng giả lập placeholder.
  + Chỉ giữ khu vực này ít chi tiết để hệ thống ghép ảnh thật ở bước sau.
`
    : "";

  return `
- Vùng ${zone.slide_number}/${totalSlides}
  + Tọa độ ngang: ${zone.start_x}px → ${zone.end_x}px
  + Kích thước vùng trên panorama: ${zone.zone_width}x${zone.zone_height}px
  + Tỷ lệ slide gốc: ${zone.source_width}:${zone.source_height}
  + Aspect ratio: ${zone.aspect_ratio.toFixed(3)}
  + Hướng: ${zone.orientation}
  + Chiếm từ ${startPct}% → ${endPct}% chiều ngang tổng thể.
${dimText}
`.trim();
}).join("\n\n");


// =====================================================
// 8. STYLE BLOCK
// =====================================================
const STYLE_BLOCK = selectedStyle
  ? `
- Phong cách minh hoạ tổng thể đã chọn cho bài này: ${selectedStyle}
- Style spec: ${styleSpec || "Không có mô tả bổ sung"}.
- Chỉ áp dụng style ở mức tinh thần bố cục nền, màu sắc và ánh sáng chung.
- KHÔNG áp dụng phần quy tắc đặt ảnh/icon cụ thể ở bước này.
`
  : "";


// =====================================================
// 9. LỌC CHỈ GIỮ BRAND RULE LIÊN QUAN NỀN/MÀU
// =====================================================
function extractBackgroundOnlyRules(text) {
  if (!text) return "";

  return String(text)
    .split(/\n+/)
    .filter(line => {
      const lower = line.toLowerCase();

      const isImageOrIconRule =
        /circle mask|khung hình bo tròn|quy tắc icon|icon đặt|ảnh chính|ảnh chụp|khung tròn/i
          .test(lower);

      return !isImageOrIconRule;
    })
    .join("\n")
    .trim();
}


// =====================================================
// 10. CÂN BẰNG THỊ GIÁC
// =====================================================
const ANTI_CENTER_NOTE = `
- QUAN TRỌNG VỀ CÂN BẰNG THỊ GIÁC:
  KHÔNG dồn trọng tâm thị giác vào chính giữa toàn bộ panorama.

- Phân bổ tương đối đều:
  + mật độ hoạ tiết
  + cường độ ánh sáng
  + độ tương phản
  + trọng lượng thị giác

  xuyên suốt tất cả ${totalSlides} vùng.

- Mỗi vùng sau khi bị cắt ra phải tự cân đối về bố cục và vẫn có thể đứng độc lập như một slide hoàn chỉnh.

- Tuy nhiên toàn bộ ${totalSlides} vùng vẫn phải có cảm giác là các phần được cắt ra từ cùng một bức tranh lớn.
`.trim();


// =====================================================
// 11. KHÔNG CHÈN CONTENT
// =====================================================
const NO_CONTENT_NOTE = `
- TUYỆT ĐỐI KHÔNG đưa ảnh sản phẩm.

- KHÔNG vẽ:
  + TEXT
  + TIÊU ĐỀ
  + SỐ
  + CHỮ VIẾT
  + LOGO
  + CTA
  + FOOTER
  + BADGE
  + KHUNG PILL
  + ICON có nội dung cụ thể.

- Đây là TEMPLATE PHÔI ĐỒ HỌA GỐC.

- Mọi nội dung thật, logo, headline và ảnh sản phẩm sẽ được hệ thống thêm ở bước sau.

- KHÔNG vẽ:
  + đường kẻ phân cách
  + viền
  + nét đứt
  + marker
  + ký hiệu chia slide.

- Ranh giới giữa ${totalSlides} vùng phải hoàn toàn vô hình.
`.trim();


// =====================================================
// 12. DANH SÁCH ĐƯỜNG BIÊN CẦN NỐI LIỀN
// =====================================================
const boundaryPositions = slideZones
  .slice(0, -1)
  .map(zone => `${zone.end_x}px`)
  .join(", ");


// =====================================================
// 13. PROMPT PANORAMA
// =====================================================
const promptText = `
Bạn là chuyên gia thiết kế đồ họa quảng cáo cao cấp cho thương hiệu chăn nuôi Ecolar.

Hãy thiết kế MỘT BỨC TRANH MASTER GRAPHIC TEMPLATE SIÊU RỘNG LIỀN MẠCH
(PANORAMA CONTINUOUS TEMPLATE).

KÍCH THƯỚC MASTER:
- Width: ${panoramaWidth}px
- Height: ${panoramaHeight}px
- Aspect ratio tổng: ${panoramaAspectRatio.toFixed(3)}:1
- Tổng số slide sau khi cắt: ${totalSlides}

Toàn bộ panorama phải được thiết kế như MỘT BỨC TRANH DUY NHẤT,
sau đó hệ thống sẽ cắt panorama thành ${totalSlides} phần riêng biệt.

===================================================
QUY CHUẨN MÀU SẮC & NỀN THƯƠNG HIỆU
===================================================

${extractBackgroundOnlyRules(brandRules.design_rule)}

- Màu sắc & Nền:
${brandRules.background_rule || ""}

${STYLE_BLOCK}

${SUPPLEMENT_NOTE}

===================================================
PHÂN BỔ CÁC VÙNG TRÊN PANORAMA
===================================================

KHÔNG chia đều các vùng.

Mỗi vùng có chiều rộng khác nhau tùy theo đúng tỷ lệ khung hình của slide tương ứng.

TỔNG KHUNG:
${panoramaSize}px

${zoneLayouts}

===================================================
YÊU CẦU LIÊN KẾT GIỮA CÁC SLIDE
===================================================

- Tạo nền xanh thương hiệu Ecolar xuyên suốt toàn bộ panorama.

- Các yếu tố:
  + gradient
  + ánh sáng
  + đường cong
  + pattern
  + lá cây
  + đường nét sinh thái
  + hoạ tiết nông trại
  + vùng sáng tối

  phải chuyển tiếp tự nhiên từ vùng này sang vùng kế tiếp.

- Các đường biên quan trọng nằm tại:
${boundaryPositions || "Không có đường biên trung gian"}

- Tại tất cả các đường biên trên:
  + Không tạo điểm ngắt.
  + Không tạo đường phân chia.
  + Không đổi màu đột ngột.
  + Không thay đổi phong cách đột ngột.
  + Các đường nét đi qua mép phải của vùng trước phải tiếp tục hợp lý ở mép trái vùng sau.

- Toàn bộ panorama phải có cảm giác như một bức tranh duy nhất được cắt thành nhiều phần.

===================================================
YÊU CẦU ĐỐI VỚI TỪNG SLIDE SAU KHI CẮT
===================================================

${ANTI_CENTER_NOTE}

===================================================
CẤM CHÈN NỘI DUNG
===================================================

${NO_CONTENT_NOTE}

===================================================
NHIỆM VỤ CUỐI CÙNG
===================================================

Hãy tạo một MASTER GRAPHIC TEMPLATE:

- Liền mạch hoàn toàn.
- Không có ranh giới nhìn thấy giữa các vùng.
- Có tính đồng nhất thương hiệu cao.
- Có sự chuyển động thị giác từ trái sang phải.
- Nhưng mỗi vùng vẫn đủ cân bằng để tồn tại độc lập sau khi bị cắt.
- Tuân thủ đúng tỷ lệ không gian của từng vùng đã mô tả.
`.trim();


// =====================================================
// 14. OUTPUT
// =====================================================
return [
  {
    json: {
      total_slides: totalSlides,

      selected_style: selectedStyle,
      chosen_style: selectedStyle,
      style_spec: styleSpec,

      panorama_size: panoramaSize,
      panorama_width: panoramaWidth,
      panorama_height: panoramaHeight,
      panorama_aspect_ratio:
        panoramaAspectRatio,

      prompt_for_panorama: promptText,

      slides_layout: slidesLayout,

      // Quan trọng cho node Cắt Panorama phía sau
      slide_zones: slideZones,

      // Danh sách điểm cắt
      cut_positions: slideZones
        .slice(0, -1)
        .map(zone => zone.end_x),

      raw_images: []
    }
  }
];

