// 1. Lấy danh sách N slide gốc từ VISUAL BRIEF BUILDER
const originalSlides = $('VISUAL BRIEF BUILDER').all().map(item => item.json);

// 2. Lấy danh sách N mảnh nền phôi từ Cắt Panorama
