const item = $input.first().json;
const body = item.body || item;

const targetRowNumber = body.target_row_number || body.row_number;
const sourceRowNumber = body.source_row_number;
const targetContentId = body.target_content_id || body.content_id || '';

// 1. Trích xuất ID folder nguồn (bài gốc)
const srcUrl = body.source_folder_url || body.source_media_url || body.source_folder_id || '';
let sourceFolderId = null;
const srcMatch = String(srcUrl).match(/folders\/([a-zA-Z0-9_-]+)/) || String(srcUrl).match(/id=([a-zA-Z0-9_-]+)/);
if (srcMatch) {
  sourceFolderId = srcMatch[1];
} else if (/^[a-zA-Z0-9_-]{20,}$/.test(String(srcUrl).trim())) {
  sourceFolderId = String(srcUrl).trim();
}

// 2. Trích xuất ID folder đích (nếu dòng đích đã lỡ có link)
const targetUrl = body.target_folder_url || body.target_media_url || '';
let targetFolderId = null;
const targetMatch = String(targetUrl).match(/folders\/([a-zA-Z0-9_-]+)/) || String(targetUrl).match(/id=([a-zA-Z0-9_-]+)/);
if (targetMatch) {
  targetFolderId = targetMatch[1];
} else if (/^[a-zA-Z0-9_-]{20,}$/.test(String(targetUrl).trim())) {
  targetFolderId = String(targetUrl).trim();
}

// 3. Tên folder đích: ưu tiên tên unique từ backend (Bai_Viet_Row_X_<content_id>),
// tránh tái sử dụng folder của dòng đã xóa (row_number tái sử dụng -> trùng folder cũ -> copy dồn).
const fallbackName = `Bai_Viet_Row_${targetRowNumber}`;
const customName = (body.target_folder_name || '').trim();
const targetFolderName = customName || fallbackName;

return [{
  json: {
    source_row_number: sourceRowNumber,
    target_row_number: targetRowNumber,
    target_content_id: targetContentId || null,
    source_folder_id: sourceFolderId,
    input_folder_id: targetFolderId,
    target_folder_name: targetFolderName
  }
}];

const targetFolderId = 
  ($('Nếu chưa có thì tạo mới Folder (Dup)').isExecuted ? $('Nếu chưa có thì tạo mới Folder (Dup)').item?.json?.id : null) ||
  ($('Tìm Folder tương ứng với Row (Dup)').isExecuted ? $('Tìm Folder tương ứng với Row (Dup)').item?.json?.id : null) ||
  ($('Tìm Folder với Id đang có (Dup)').isExecuted ? $('Tìm Folder với Id đang có (Dup)').item?.json?.id : null);

const sourceFolderId = $('Trích xuất Folder ID (Dup)').first().json.source_folder_id;
const targetRowNumber = $('Trích xuất Folder ID (Dup)').first().json.target_row_number;

return [{
  json: {
    target_folder_id: targetFolderId,
    target_folder_url: `https://drive.google.com/drive/folders/${targetFolderId}`,
    source_folder_id: sourceFolderId,
    target_row_number: targetRowNumber
  }
}];

