parameters.jsCode:
// Lọc idempotent: chỉ copy file nguồn CHƯA có trong folder đích (so theo tên).
// Đồng thời chặn self-copy (source_folder_id == target_folder_id) -> trả về rỗng để skip.
const det = $('Xác Định Folder Đích (Dup)').first().json;
const srcId = det.source_folder_id || null;
const tgtId = det.target_folder_id || null;

// Self-copy guard: cùng 1 folder -> không copy gì cả (tránh nhân đôi trong chính folder nguồn)
if (srcId && tgtId && srcId === tgtId) {
  return [{ json: { _skipped: 'self_copy_guard' } }];
}

let srcItems = [];
try { srcItems = $('Liệt Kê File Bài Gốc (Dup)').all(); } catch (e) { srcItems = []; }
let tgtItems = [];
try { tgtItems = $input.all(); } catch (e) { tgtItems = []; }

const tgtNames = new Set(
  tgtItems.map((i) => i.json && i.json.name).filter((n) => typeof n === 'string' && n)
);
// Drive cho phép trùng tên file: file đã copy trước đó vẫn nằm trong đích -> phải skip theo tên,
// nếu không webhook gọi lại lần 2 sẽ copy dồn gấp đôi/gấp ba.
const filtered = srcItems.filter((i) => i.json && i.json.id && !tgtNames.has(i.json.name));

if (filtered.length === 0) {
  return [{ json: {} }];
}
return filtered.map((i) => ({ json: i.json }));
